using System.Security.Cryptography;using System.Text;using Npgsql;using UDrive.Api.Common;using UDrive.Api.Models;
namespace UDrive.Api.Services;
public sealed class SafetyService(string cs){NpgsqlConnection Open()=>new(cs);static void P(NpgsqlCommand c,string n,object? v)=>c.Parameters.AddWithValue(n,v??DBNull.Value);static string Hash(string s)=>Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(s)));
async Task<bool> CanAccess(NpgsqlConnection cn,Guid user,Guid booking,CancellationToken ct){await using var c=new NpgsqlCommand("select exists(select 1 from udrive.bookings b left join udrive.driver_profiles d on d.id=b.driver_profile_id where b.id=@b and (b.customer_user_id=@u or d.user_id=@u))",cn);P(c,"b",booking);P(c,"u",user);return (bool)(await c.ExecuteScalarAsync(ct)??false);}
public async Task<ServiceResult<IReadOnlyList<TrustedContactDto>>> Contacts(Guid user,CancellationToken ct){await using var cn=Open();await cn.OpenAsync(ct);var x=new List<TrustedContactDto>();await using var c=new NpgsqlCommand("select id,name,phone_number,relationship,is_primary,created_at from udrive.trusted_contacts where user_id=@u and is_active order by is_primary desc,created_at",cn);P(c,"u",user);await using var r=await c.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))x.Add(new(r.GetGuid(0),r.GetString(1),r.GetString(2),r.GetString(3),r.GetBoolean(4),r.GetFieldValue<DateTimeOffset>(5)));return ServiceResult<IReadOnlyList<TrustedContactDto>>.Ok(x);}
public async Task<ServiceResult<TrustedContactDto>> SaveContact(Guid user,TrustedContactRequest x,CancellationToken ct){if(string.IsNullOrWhiteSpace(x.Name)||string.IsNullOrWhiteSpace(x.PhoneNumber))return ServiceResult<TrustedContactDto>.Fail(400,"invalid_contact","Name and phone are required.");await using var cn=Open();await cn.OpenAsync(ct);await using var tx=await cn.BeginTransactionAsync(ct);if(x.IsPrimary){await using var clear=new NpgsqlCommand("update udrive.trusted_contacts set is_primary=false,updated_at=now() where user_id=@u",cn,tx);P(clear,"u",user);await clear.ExecuteNonQueryAsync(ct);}await using var c=new NpgsqlCommand("insert into udrive.trusted_contacts(user_id,name,phone_number,relationship,is_primary) values(@u,@n,@p,@r,@i) returning id,created_at",cn,tx);P(c,"u",user);P(c,"n",x.Name.Trim());P(c,"p",x.PhoneNumber.Trim());P(c,"r",x.Relationship.Trim());P(c,"i",x.IsPrimary);await using var rd=await c.ExecuteReaderAsync(ct);await rd.ReadAsync(ct);var dto=new TrustedContactDto(rd.GetGuid(0),x.Name.Trim(),x.PhoneNumber.Trim(),x.Relationship.Trim(),x.IsPrimary,rd.GetFieldValue<DateTimeOffset>(1));await rd.DisposeAsync();await tx.CommitAsync(ct);return ServiceResult<TrustedContactDto>.Created(dto);}
public async Task<ServiceResult<bool>> DeleteContact(Guid user,Guid id,CancellationToken ct){await using var cn=Open();await cn.OpenAsync(ct);await using var c=new NpgsqlCommand("update udrive.trusted_contacts set is_active=false,is_primary=false,updated_at=now() where id=@id and user_id=@u",cn);P(c,"id",id);P(c,"u",user);return ServiceResult<bool>.Ok(await c.ExecuteNonQueryAsync(ct)>0);}
public async Task<ServiceResult<SafetyCaseDto>> RaiseSos(Guid user,RaiseSosRequest x,CancellationToken ct){await using var cn=Open();await cn.OpenAsync(ct);if(x.BookingId is not null&&!await CanAccess(cn,user,x.BookingId.Value,ct))return ServiceResult<SafetyCaseDto>.Fail(403,"booking_access_denied","You cannot raise an SOS for this booking.");var reference=$"SOS-{DateTime.UtcNow:yyMMdd}-{RandomNumberGenerator.GetInt32(100000,999999)}";await using var tx=await cn.BeginTransactionAsync(ct);Guid id;DateTimeOffset created;await using(var c=new NpgsqlCommand(@"insert into udrive.emergency_cases(case_reference,booking_id,raised_by_user_id,emergency_type,description,latitude,longitude,accuracy_meters) values(@r,@b,@u,@t,@d,@lat,@lng,@a) returning id,created_at",cn,tx)){P(c,"r",reference);P(c,"b",x.BookingId);P(c,"u",user);P(c,"t",string.IsNullOrWhiteSpace(x.EmergencyType)?"SOS":x.EmergencyType);P(c,"d",x.Description.Trim());P(c,"lat",x.Latitude);P(c,"lng",x.Longitude);P(c,"a",x.AccuracyMeters);await using var r=await c.ExecuteReaderAsync(ct);await r.ReadAsync(ct);id=r.GetGuid(0);created=r.GetFieldValue<DateTimeOffset>(1);}await using(var n=new NpgsqlCommand(@"insert into udrive.notifications(id,user_id,type,title,body,data_json,action_path,created_at,updated_at) select gen_random_uuid(),u.id,'Emergency','Emergency SOS raised',@body,jsonb_build_object('caseId',@id),'/safety',now(),now() from udrive.users u where u.role in ('SuperAdmin','Admin','Manager','Operations','SafetyOfficer') and u.account_status not in ('Suspended','Rejected')",cn,tx)){P(n,"body",$"{reference}: {x.Description}");P(n,"id",id);await n.ExecuteNonQueryAsync(ct);}if(x.BookingId is not null){await using var op=new NpgsqlCommand("update udrive.trip_operations set emergency_raised_at=coalesce(emergency_raised_at,now()),trip_status='Emergency',last_activity_at=now(),updated_at=now(),version=version+1 where booking_id=@b",cn,tx);P(op,"b",x.BookingId);await op.ExecuteNonQueryAsync(ct);}await tx.CommitAsync(ct);return ServiceResult<SafetyCaseDto>.Created(new(id,reference,x.BookingId,null,"You",x.EmergencyType,"Critical","Open",x.Description,x.Latitude,x.Longitude,null,null,0,created,null,null),"SOS sent to uDrive safety operations.");}
public async Task<ServiceResult<TripPinDto>> CreatePin(Guid user,Guid booking,CancellationToken ct){await using var cn=Open();await cn.OpenAsync(ct);if(!await CanAccess(cn,user,booking,ct))return ServiceResult<TripPinDto>.Fail(403,"booking_access_denied","You cannot access this trip PIN.");var pin=RandomNumberGenerator.GetInt32(1000,10000).ToString();var exp=DateTimeOffset.UtcNow.AddHours(24);await using var c=new NpgsqlCommand("insert into udrive.trip_safety_pins(booking_id,pin_hash,expires_at) values(@b,@h,@e) on conflict(booking_id) do update set pin_hash=excluded.pin_hash,failed_attempts=0,locked_until=null,verified_at=null,verified_by_user_id=null,created_at=now(),expires_at=excluded.expires_at",cn);P(c,"b",booking);P(c,"h",Hash(pin));P(c,"e",exp);await c.ExecuteNonQueryAsync(ct);return ServiceResult<TripPinDto>.Ok(new(booking,pin,exp));}
public async Task<ServiceResult<bool>> VerifyPin(Guid user,Guid booking,VerifyTripPinRequest x,CancellationToken ct){await using var cn=Open();await cn.OpenAsync(ct);if(!await CanAccess(cn,user,booking,ct))return ServiceResult<bool>.Fail(403,"booking_access_denied","You cannot verify this trip PIN.");await using var c=new NpgsqlCommand("select pin_hash,failed_attempts,locked_until,expires_at,verified_at from udrive.trip_safety_pins where booking_id=@b",cn);P(c,"b",booking);await using var r=await c.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))return ServiceResult<bool>.Fail(404,"pin_not_found","Trip PIN has not been created.");if(!r.IsDBNull(4))return ServiceResult<bool>.Ok(true);var now=DateTimeOffset.UtcNow;if(!r.IsDBNull(2)&&r.GetFieldValue<DateTimeOffset>(2)>now)return ServiceResult<bool>.Fail(429,"pin_locked","Too many attempts. Try again later.");if(r.GetFieldValue<DateTimeOffset>(3)<now)return ServiceResult<bool>.Fail(410,"pin_expired","Trip PIN expired.");var ok=CryptographicOperations.FixedTimeEquals(Convert.FromHexString(r.GetString(0)),Convert.FromHexString(Hash(x.Pin.Trim())));var attempts=r.GetInt32(1);await r.DisposeAsync();await using var u=new NpgsqlCommand(ok?"update udrive.trip_safety_pins set verified_at=now(),verified_by_user_id=@u where booking_id=@b":"update udrive.trip_safety_pins set failed_attempts=failed_attempts+1,locked_until=case when failed_attempts+1>=5 then now()+interval '15 minutes' else null end where booking_id=@b",cn);P(u,"u",user);P(u,"b",booking);await u.ExecuteNonQueryAsync(ct);return ok?ServiceResult<bool>.Ok(true,"Trip PIN verified."):ServiceResult<bool>.Fail(400,"invalid_pin","The PIN is incorrect.");}
public async Task<ServiceResult<SafetyReportDto>> Report(Guid user,CreateSafetyReportRequest x,CancellationToken ct){await using var cn=Open();await cn.OpenAsync(ct);if(!await CanAccess(cn,user,x.BookingId,ct))return ServiceResult<SafetyReportDto>.Fail(403,"booking_access_denied","You cannot report this booking.");await using var c=new NpgsqlCommand(@"insert into udrive.safety_reports(booking_id,reported_by_user_id,report_type,severity,description,latitude,longitude) values(@b,@u,@t,@s,@d,@lat,@lng) returning id,created_at",cn);P(c,"b",x.BookingId);P(c,"u",user);P(c,"t",x.ReportType);P(c,"s",x.Severity);P(c,"d",x.Description);P(c,"lat",x.Latitude);P(c,"lng",x.Longitude);await using var r=await c.ExecuteReaderAsync(ct);await r.ReadAsync(ct);return ServiceResult<SafetyReportDto>.Created(new(r.GetGuid(0),x.BookingId,"",x.ReportType,x.Severity,x.Description,"Open",r.GetFieldValue<DateTimeOffset>(1)));}
public async Task<ServiceResult<SafetyDashboardDto>> Dashboard(CancellationToken ct){await using var cn=Open();await cn.OpenAsync(ct);await using var c=new NpgsqlCommand(@"select count(*) filter(where status not in('Resolved','FalseAlarm')),count(*) filter(where acknowledged_at is null and status not in('Resolved','FalseAlarm')),count(*) filter(where severity='Critical' and status not in('Resolved','FalseAlarm')),count(*) filter(where status in('Acknowledged','InProgress','Escalated')),count(*) filter(where resolved_at::date=current_date),(select count(*) from udrive.driver_latest_locations l join udrive.trip_operations t on t.booking_id=l.booking_id where t.trip_status in('DriverEnRoute','DriverArrived','TripStarted','Emergency') and l.server_timestamp<now()-interval '60 seconds'),(select count(*) from udrive.driver_compliance_documents where expires_at<=current_date+interval '30 days' and status<>'Expired') from udrive.emergency_cases",cn);await using var r=await c.ExecuteReaderAsync(ct);await r.ReadAsync(ct);return ServiceResult<SafetyDashboardDto>.Ok(new(r.GetInt32(0),r.GetInt32(1),r.GetInt32(2),r.GetInt32(3),r.GetInt32(4),r.GetInt32(5),r.GetInt32(6)));}
public async Task<ServiceResult<IReadOnlyList<SafetyCaseDto>>> Cases(string? status,CancellationToken ct){await using var cn=Open();await cn.OpenAsync(ct);var list=new List<SafetyCaseDto>();await using var c=new NpgsqlCommand(@"select e.id,e.case_reference,e.booking_id,b.booking_reference,coalesce(u.full_name,u.phone_number,'User'),e.emergency_type,e.severity,e.status,e.description,e.latitude,e.longitude,coalesce(a.full_name,a.phone_number),e.resolution_notes,e.version,e.created_at,e.acknowledged_at,e.resolved_at from udrive.emergency_cases e join udrive.users u on u.id=e.raised_by_user_id left join udrive.users a on a.id=e.assigned_admin_user_id left join udrive.bookings b on b.id=e.booking_id where (@s is null or e.status=@s) order by case when e.severity='Critical' then 0 else 1 end,e.created_at desc limit 200",cn);P(c,"s",string.IsNullOrWhiteSpace(status)?null:status);await using var r=await c.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))list.Add(new(r.GetGuid(0),r.GetString(1),r.IsDBNull(2)?null:r.GetGuid(2),r.IsDBNull(3)?null:r.GetString(3),r.GetString(4),r.GetString(5),r.GetString(6),r.GetString(7),r.GetString(8),r.IsDBNull(9)?null:r.GetDouble(9),r.IsDBNull(10)?null:r.GetDouble(10),r.IsDBNull(11)?null:r.GetString(11),r.IsDBNull(12)?null:r.GetString(12),r.GetInt32(13),r.GetFieldValue<DateTimeOffset>(14),r.IsDBNull(15)?null:r.GetFieldValue<DateTimeOffset>(15),r.IsDBNull(16)?null:r.GetFieldValue<DateTimeOffset>(16)));return ServiceResult<IReadOnlyList<SafetyCaseDto>>.Ok(list);}
public async Task<ServiceResult<bool>> Update(Guid actor,Guid id,UpdateEmergencyRequest x,CancellationToken ct){var allowed=new[]{"Open","Acknowledged","InProgress","Escalated","Resolved","FalseAlarm"};if(!allowed.Contains(x.Status))return ServiceResult<bool>.Fail(400,"invalid_status","Invalid emergency status.");await using var cn=Open();await cn.OpenAsync(ct);await using var c=new NpgsqlCommand(@"update udrive.emergency_cases set status=@s,assigned_admin_user_id=@a,resolution_notes=@n,acknowledged_at=case when @s in('Acknowledged','InProgress','Escalated','Resolved') then coalesce(acknowledged_at,now()) else acknowledged_at end,resolved_at=case when @s in('Resolved','FalseAlarm') then now() else null end,updated_at=now(),version=version+1 where id=@id and version=@v",cn);P(c,"s",x.Status);P(c,"a",x.AssignedAdminUserId);P(c,"n",x.ResolutionNotes);P(c,"id",id);P(c,"v",x.ExpectedVersion);var n=await c.ExecuteNonQueryAsync(ct);if(n==0)return ServiceResult<bool>.Fail(409,"case_changed","Emergency case changed. Refresh and retry.");await using var e=new NpgsqlCommand("insert into udrive.emergency_events(emergency_case_id,actor_user_id,event_type,message) values(@id,@u,'StatusChanged',@m)",cn);P(e,"id",id);P(e,"u",actor);P(e,"m",$"Status changed to {x.Status}. {x.ResolutionNotes}");await e.ExecuteNonQueryAsync(ct);return ServiceResult<bool>.Ok(true);}
}
